module logic;
use model {Summary,Event};
use util {reverse};

record LedgerState {
 pending:List<Event>,
 balance:I64,
 rejected:I64,
 peak:I64,
 locked:Bool,
 audit:List<I64>
}

fn run(events:List<Event>,initial:I64)->Summary {
 let finalState=fold(i in List::length(events),cursor:LedgerState=LedgerState {
  pending:events,balance:initial,rejected:0,peak:initial,
  locked:false,audit:List::empty<I64>()
 }) {
  let updated=match (List::head(cursor.pending)) {
   Credit(amount)=> if amount<0 || amount>1000000 {
    LedgerState {...cursor,rejected:cursor.rejected+1}
   } else {
    LedgerState {...cursor,balance:cursor.balance+amount}
   },
   Debit(amount)=> if amount<0 || amount>1000000 || cursor.locked || amount>cursor.balance {
    LedgerState {...cursor,rejected:cursor.rejected+1}
   } else {
    LedgerState {...cursor,balance:cursor.balance-amount}
   },
   Lock=> LedgerState {...cursor,locked:true},
   Unlock=> LedgerState {...cursor,locked:false}
  };
  LedgerState {
   ...updated,
   pending:List::tail(cursor.pending),
   peak:if updated.balance>cursor.peak {updated.balance} else {cursor.peak},
   audit:List::prepend(updated.balance,cursor.audit)
  }
 };
 Summary {balance:finalState.balance,rejected:finalState.rejected,peak:finalState.peak,audit:reverse(finalState.audit)}
}

